package com.heathen.persephone;
import android.app.*;
import android.graphics.*;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
/** Local creature library. Manual names/functions do not alter detector evidence or radio authorization. */
@android.annotation.SuppressLint("SetTextI18n")
public final class SignalDexActivity extends Activity {
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);}
    @Override protected void onResume(){super.onResume();if(!PinGate.require(this))return;render();}
    private void render(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(40),dp(18),dp(24));root.setBackground(new HudBackground());root.addView(label("SIGNAL DEX // CREATURE ARCHIVE",22,0xffffde43));root.addView(label("Local reception sightings unlock entries. These are creature representations of evidence, not confirmed device identities. Demo sightings are counted separately.",13,0xffafc4ce));
        for(JSONObject ping:PingStore.get(this).list())DexLedger.record(this,ping);for(JSONObject creature:DexCatalog.entries(this)){String id=creature.optString("id");int count=DexLedger.count(this,id,false),demo=DexLedger.count(this,id,true);int color=Color.parseColor(creature.optString("color"));LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(12),dp(14),dp(12),dp(14));card.addView(new GlyphView(this,id,color),new LinearLayout.LayoutParams(-1,dp(90)));card.addView(label(DexCatalog.title(this,id),20,color));card.addView(label("FIELD "+count+" // DEMO "+demo+" // "+(count>0?"OBSERVED":"UNSEEN"),12,0xffd4e5ec));card.addView(label(creature.optString("description"),13,0xffafc4ce));card.addView(label("FUNCTION\n"+DexCatalog.function(this,creature),14,color));Button edit=new Button(this);edit.setText("Assign name / function");HudBackground.style(edit);edit.setOnClickListener(v->{if(PinGate.require(this))customize(creature);});card.addView(edit);root.addView(card);}
        Button export=new Button(this);export.setText("Export Signal Dex to chosen SD folder");HudBackground.style(export);export.setOnClickListener(v->{if(!PinGate.require(this))return;String tree=getSharedPreferences("settings",0).getString("tree","");if(tree.isEmpty()){new AlertDialog.Builder(this).setMessage("Choose a save folder in Desk → Logs first.").setPositiveButton("OK",null).show();return;}export.setEnabled(false);new Thread(()->{try{DexExport.export(this,android.net.Uri.parse(tree));runOnUiThread(()->{export.setEnabled(true);android.widget.Toast.makeText(this,"Dex exported; private progress retained",android.widget.Toast.LENGTH_LONG).show();});}catch(Exception error){runOnUiThread(()->{export.setEnabled(true);android.widget.Toast.makeText(this,"Export failed; private progress retained",android.widget.Toast.LENGTH_LONG).show();});}},"dex-export").start();});root.addView(export);
        Button done=new Button(this);done.setText("Return to Field Map");HudBackground.style(done);done.setOnClickListener(v->finish());root.addView(done);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(root);setContentView(scroll);
    }
    private void customize(JSONObject creature){String id=creature.optString("id");LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(18),dp(8),dp(18),dp(8));EditText name=new EditText(this);name.setHint("Creature name");name.setText(DexCatalog.title(this,id));EditText function=new EditText(this);function.setHint("Function / training description");function.setText(DexCatalog.function(this,creature));function.setMinLines(3);box.addView(name);box.addView(function);box.addView(label("Functions are descriptions for your creature design. Existing radio actions retain their consent and passcode gates.",12,0xffafc4ce));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Customize creature").setView(box).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{if(!PinGate.require(this)){dialog.dismiss();return;}try{DexCatalog.customize(this,id,name.getText().toString(),function.getText().toString());dialog.dismiss();render();}catch(Exception error){name.setError(error.getMessage());}}));dialog.show();}
    private TextView label(String text,int size,int color){TextView view=new TextView(this);view.setText(text);view.setTextSize(size);view.setTextColor(color);view.setTypeface(Typeface.MONOSPACE);view.setPadding(0,dp(4),0,dp(4));return view;}
    private int dp(int value){return (int)(value*getResources().getDisplayMetrics().density+.5f);}
    @android.annotation.SuppressLint("ViewConstructor") // Programmatic catalog glyph only.
    private static final class GlyphView extends View {final String id;final int color;final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);GlyphView(android.content.Context context,String id,int color){super(context);this.id=id;this.color=color;setContentDescription("Original "+id+" circuit creature silhouette");}protected void onDraw(Canvas canvas){super.onDraw(canvas);paint.setColor(color);CreatureGlyph.draw(canvas,paint,getWidth()/2f,getHeight()/2f,getHeight()*.28f,id);}}
}
